package com.shortner.agent;
import com.shortner.agent.orchestration.model.*; import com.shortner.agent.orchestration.service.OrchestrationService; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest class OrchestrationTest { @Autowired OrchestrationService service;
 @Test void graphEnforcesApprovalAndSynchronizesRelease() {long id=service.start("greenfield","create short links").getId(); assertEquals(RunStatus.READY,service.view(id).stages().stream().filter(s->s.getStage()==Stage.REQUIREMENTS).findFirst().orElseThrow().getStatus()); service.execute(id,Stage.REQUIREMENTS,true,"normalized acceptance criteria"); assertEquals(RunStatus.WAITING_APPROVAL,service.view(id).stages().stream().filter(s->s.getStage()==Stage.DESIGN).findFirst().orElseThrow().getStatus()); service.approve(id,Stage.DESIGN,"architect"); service.execute(id,Stage.DESIGN,true,"ADR"); service.execute(id,Stage.IMPLEMENTATION,true,"PR"); service.execute(id,Stage.TESTING,true,"tests"); service.execute(id,Stage.DOCUMENTATION,true,"docs"); assertEquals(RunStatus.READY,service.view(id).stages().stream().filter(s->s.getStage()==Stage.RELEASE_READINESS).findFirst().orElseThrow().getStatus()); }
}
